class Solution {
    public boolean isPossible(int[] target){
        PriorityQueue<Long> heap=new PriorityQueue<>(Collections.reverseOrder());
        long total=0;
        for(int value:target){
            heap.offer((long)value);
            total+=value;
        }while(true){
            long maximum=heap.poll(),rest=total-maximum;
            if(maximum==1||rest==1)return true;
            if(rest==0||rest>=maximum||maximum%rest==0)return false;
            long previous=maximum%rest;
            total=rest+previous;
            heap.offer(previous);
        }
    }
}

code.kotlin:
class Solution {
    fun isPossible(target:IntArray):Boolean{
        val heap=java.util.PriorityQueue<Long>(reverseOrder());
        var total=0L;
        for(value in target){
            heap.add(value.toLong());
            total+=value
        };
        while(true){
            val maximum=heap.remove();
            val rest=total-maximum;
            if(maximum==1L||rest==1L)return true;
            if(rest==0L||rest>=maximum||maximum%rest==0L)return false;
            val previous=maximum%rest;
            total=rest+previous;
            heap.add(previous)
        }
    }
}

